import re,glob,collections
cnt=collections.Counter();ex={}
for f in sorted(glob.glob('*.txt')):
    pages=re.split(r'^=== page \d+\s*$',open(f).read(),flags=re.M)
    for p in pages[1:]:
        m=re.search(r'^\s*Respondent:(.*?)^\s*Other Party',p,re.S|re.M)
        if m and not m.group(1).strip() and 'finds the following' in p:
            i=p.index('Respondent:'); j=p.index('finds the following')
            seg=[l.strip() for l in p[i:j].split('\n') if l.strip()]
            sig=tuple(re.sub(r'[A-Za-z]','a',re.sub(r'\d','9',l))[:6] if not l.split(':')[0] in('Respondent','Other Party','Case Number','Date of Advisory Meeting','Date of Damage','Damage Location') else l.split(':')[0][:8]+(':+' if l.split(':',1)[1].strip() else ':') for l in seg)
            cnt[sig]+=1; ex[sig]=(f,seg)
for s,c in cnt.most_common(): print(c,ex[s])
